import { useEffect, useRef, useState } from "react";

/**
 * SmartCargo animated loading screen.
 *
 * Usage:
 *   const [dataReady, setDataReady] = useState(false);
 *   const [showLoader, setShowLoader] = useState(true);
 *
 *   useEffect(() => {
 *     fetchInitialData().then(() => setDataReady(true));
 *   }, []);
 *
 *   return (
 *     <>
 *       {showLoader && (
 *         <LoadingScreen
 *           isLoading={!dataReady}
 *           onFinished={() => setShowLoader(false)}
 *         />
 *       )}
 *       <App />
 *     </>
 *   );
 *
 * Props:
 *   isLoading    - boolean. Set to false once your app's data/assets are ready.
 *   minDuration  - number (ms). Loader stays on screen at least this long,
 *                  even if isLoading turns false sooner. Default 2200.
 *   onFinished   - callback fired after the fade-out finishes. Use it to
 *                  unmount the component (see example above).
 */
type LoadingScreenProps = {
  isLoading?: boolean;
  minDuration?: number;
  onFinished?: () => void;
};

export default function LoadingScreen({
  isLoading = true,
  minDuration = 2200,
  onFinished,
}: LoadingScreenProps) {
  const [visible, setVisible] = useState(true);
  const [fading, setFading] = useState(false);
  const [minTimeElapsed, setMinTimeElapsed] = useState(false);
  const onFinishedRef = useRef(onFinished);

  useEffect(() => {
    onFinishedRef.current = onFinished;
  }, [onFinished]);

  useEffect(() => {
    const t = setTimeout(() => setMinTimeElapsed(true), minDuration);
    return () => clearTimeout(t);
  }, [minDuration]);

  useEffect(() => {
    if (!isLoading && minTimeElapsed) setFading(true);
  }, [isLoading, minTimeElapsed]);

  useEffect(() => {
    if (!fading) return;
    const t = setTimeout(() => {
      setVisible(false);
      onFinishedRef.current?.();
    }, 600); // must match --sc-fade-duration below
    return () => clearTimeout(t);
  }, [fading]);

  if (!visible) return null;

  return (
    <div className={`sc-loader${fading ? " sc-loader--hide" : ""}`}>
      <style>{STYLES}</style>
      <div className="sc-logo-stage">
        <img className="sc-logo-base" src={LOGO_BASE_IMG} alt="SmartCargo" />
        <img className="sc-logo-arrow" src={ARROW_IMG} alt="" />
      </div>
      <div className="sc-loading-text">Loading</div>
    </div>
  );
}

const LOGO_BASE_IMG = "data:image/png;base64,";
const ARROW_IMG = "data:image/png;base64,";

const STYLES = `
.sc-loader {
  --sc-purple: #4B0769;
  --sc-bg-light: #ffffff;
  --sc-fade-duration: 0.6s;
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 24px;
  background: var(--sc-bg-light);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  transition: opacity var(--sc-fade-duration) ease;
}
.sc-loader--hide {
  opacity: 0;
  pointer-events: none;
}

.sc-logo-stage {
  position: relative;
  width: min(85vw, 460px);
  aspect-ratio: 3166 / 1072;
  opacity: 0;
  animation: sc-stage-in 0.5s ease forwards;
}
@keyframes sc-stage-in {
  to { opacity: 1; }
}

.sc-logo-base {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  -webkit-user-select: none;
  user-select: none;
}

/* Full arrow (swoosh + triangle) positioned exactly where it sits
   in the original artwork. */
.sc-logo-arrow {
  position: absolute;
  left: 0%;
  top: 41.60%;
  width: 44.03%;
  height: 58.40%;
  -webkit-user-select: none;
  user-select: none;
  clip-path: inset(0 100% 0 0);
  animation: sc-grow-arrow 1.8s ease-in-out infinite;
}

/* Reveals the arrow left to right: the visible window widens from
   0 to full width, so its width and visible height grow together. */
@keyframes sc-grow-arrow {
  0%   { clip-path: inset(0 100% 0 0); }
  40%  { clip-path: inset(0 0% 0 0); }
  65%  { clip-path: inset(0 0% 0 0); }
  100% { clip-path: inset(0 100% 0 0); }
}

.sc-loading-text {
  font-size: 13px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--sc-purple);
  opacity: 0.85;
}
`;